import torch
from comfy_api.latest import io
from comfy_api.input import CurveInput
from ._helpers import _apply_mask_to_image, _apply_color_adjust, _prepare_effect_mask, _resolve_mask_output_source, _scalar, _select_media_tensor, apply_per_frame_bypass
from ._progress import start_progress
from ._preview import build_node_preview_result
from .core.curve import CURVE_LUT_SIZE, apply_curve_lut, is_identity_lut

def _apply_master_curve(image, curve):
    if curve is None:
        return image
    lut = torch.from_numpy(CurveInput.from_raw(curve).to_lut(CURVE_LUT_SIZE)).float()
    if is_identity_lut(lut):
        return image
    return apply_curve_lut(image, lut)

